// Universe Render Reference
//
// This file is used to render the universe and compare the results to a reference
// render. It is used to ensure that the renderer is working correctly and to
// compare the performance of the renderer.
//
// Reference images are generated by running the renderer with the --reset flag.
// This will create a new reference for each of the renderers.

#include <inttypes.h>
#include <SDL2/SDL.h>
