#include "sprite_renderer.h"

// High-resolution timer for performance measurement
static uint64_t get_time_ns(void)
{
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint64_t)ts.tv_sec * 1000000000ULL + (uint64_t)ts.tv_nsec;
}

// Helper function to convert string to lowercase
static char* strtolower(char* str) {
  for (char* p = str; *p; ++p) *p = tolower(*p);
  return str;
}

// Render a top-down map using the highest solid voxel per (x,y)
static void render_topdown_highest(SDL_Renderer *ren, const World *w, int screen_w, int screen_h)
{
  if (!ren || !w || screen_w <= 0 || screen_h <= 0)
    return;
  int cell_w = screen_w / (int)w->width;
  int cell_h = screen_h / (int)w->height;
  if (cell_w < 1)
    cell_w = 1;
  if (cell_h < 1)
    cell_h = 1;
  for (uint32_t y = 0; y < w->height; y++)
  {
    for (uint32_t x = 0; x < w->width; x++)
    {
      int top_z = -1;
      for (int z = (int)w->depth - 1; z >= 0; z--)
      {
        const Voxel *vz = world_voxel_cptr_fast((World *)w, (int)x, (int)y, z);
        if (vz && vz->type != VOXEL_AIR)
        {
          top_z = z;
          break;
        }
      }
      uint8_t r = 20, g = 22, b = 35; // background if no solid
      if (top_z >= 0)
      {
        Voxel *v = world_get_voxel((World *)w, x, y, (uint32_t)top_z);
        if (v)
        {
          world_voxel_type_color(v->type, &r, &g, &b);
        }
      }
      SDL_SetRenderDrawColor(ren, r, g, b, 255);
      SDL_Rect rect = {(int)(x * cell_w), (int)(y * cell_h), cell_w, cell_h};
      SDL_RenderFillRect(ren, &rect);
    }
  }
}

// Render with CPU renderer at different optimization levels and export bitmaps
static void render_cpu_optimization_phases(SDL_Renderer *ren, IsometricRenderer *ir, int screen_w, int screen_h)
{
  printf("[CPU-OPT] Rendering optimization phases...\n");

  // Initialize CPU renderer
  cpu_renderer_init_color_table();

  // Define optimization phases to test
  struct {
    const char *name;
    const char *filename;
    CPURenderOptimizations flags;
  } phases[] = {
    {"No Optimizations", "assets/cpu_phase_none.bmp", CPU_RENDER_OPT_NONE},
    {"Chunk Culling", "assets/cpu_phase_chunk.bmp", CPU_RENDER_OPT_CHUNK_CULLING},
    {"Screen Culling", "assets/cpu_phase_screen.bmp", CPU_RENDER_OPT_CHUNK_CULLING | CPU_RENDER_OPT_SCREEN_CULLING},
    {"No Face Culling (Quality)", "assets/cpu_phase_quality.bmp", CPU_RENDER_OPT_CHUNK_CULLING | CPU_RENDER_OPT_SCREEN_CULLING | CPU_RENDER_OPT_COLOR_TABLE},
    {"With Face Culling (Performance)", "assets/cpu_phase_performance.bmp", CPU_RENDER_OPT_CHUNK_CULLING | CPU_RENDER_OPT_SCREEN_CULLING | CPU_RENDER_OPT_COLOR_TABLE | CPU_RENDER_OPT_FACE_CULLING},
    {"Batch Rendering", "assets/cpu_phase_batch.bmp", CPU_RENDER_OPT_CHUNK_CULLING | CPU_RENDER_OPT_SCREEN_CULLING | CPU_RENDER_OPT_COLOR_TABLE | CPU_RENDER_OPT_BATCH_RENDERING},
    {"Loop Unrolling", "assets/cpu_phase_loop.bmp", CPU_RENDER_OPT_CHUNK_CULLING | CPU_RENDER_OPT_SCREEN_CULLING | CPU_RENDER_OPT_COLOR_TABLE | CPU_RENDER_OPT_BATCH_RENDERING | CPU_RENDER_OPT_LOOP_UNROLLING},
    {"Memory Alignment", "assets/cpu_phase_memory.bmp", CPU_RENDER_OPT_CHUNK_CULLING | CPU_RENDER_OPT_SCREEN_CULLING | CPU_RENDER_OPT_COLOR_TABLE | CPU_RENDER_OPT_BATCH_RENDERING | CPU_RENDER_OPT_LOOP_UNROLLING | CPU_RENDER_OPT_MEMORY_ALIGNMENT},
    {"SIMD Hints", "assets/cpu_phase_simd.bmp", CPU_RENDER_OPT_CHUNK_CULLING | CPU_RENDER_OPT_SCREEN_CULLING | CPU_RENDER_OPT_COLOR_TABLE | CPU_RENDER_OPT_BATCH_RENDERING | CPU_RENDER_OPT_LOOP_UNROLLING | CPU_RENDER_OPT_MEMORY_ALIGNMENT | CPU_RENDER_OPT_SIMD_HINTS},
    {"Cache Optimization", "assets/cpu_phase_cache.bmp", CPU_RENDER_OPT_CHUNK_CULLING | CPU_RENDER_OPT_SCREEN_CULLING | CPU_RENDER_OPT_COLOR_TABLE | CPU_RENDER_OPT_BATCH_RENDERING | CPU_RENDER_OPT_LOOP_UNROLLING | CPU_RENDER_OPT_MEMORY_ALIGNMENT | CPU_RENDER_OPT_SIMD_HINTS | CPU_RENDER_OPT_CACHE_OPTIMIZATION},
    {"All Optimizations", "assets/cpu_phase_all.bmp", CPU_RENDER_OPT_ALL}
  };

  int num_phases = sizeof(phases) / sizeof(phases[0]);

  for (int phase = 0; phase < num_phases; phase++) {
    printf("[CPU-OPT] Phase %d/%d: %s\n", phase + 1, num_phases, phases[phase].name);

    // Configure CPU renderer
    CPURendererConfig config = {
      .flags = phases[phase].flags,
      .batch_size = 1024,
      .chunk_size_x = 16,
      .chunk_size_y = 16,
      .chunk_size_z = 256,
      .enable_grid = false,
      .enable_debug_overlay = false,
      .max_visible_voxels = 100000,
      .culling_margin = 32.0f
    };

    // Reset stats for this phase
    cpu_renderer_reset_stats();

    // Render with CPU renderer
    Uint64 start_time = SDL_GetPerformanceCounter();
    cpu_renderer_render_optimized(ir, ren, &config);
    Uint64 end_time = SDL_GetPerformanceCounter();

    // Calculate performance
    double freq = (double)SDL_GetPerformanceFrequency();
    double render_time_ms = (double)(end_time - start_time) * 1000.0 / freq;

    // Get statistics
    CPURendererStats stats = cpu_renderer_get_stats();

    // Export bitmap
    SDL_Surface *surf32 = SDL_CreateRGBSurfaceWithFormat(0, screen_w, screen_h, 32, SDL_PIXELFORMAT_ARGB8888);
    if (surf32) {
      if (SDL_RenderReadPixels(ren, NULL, SDL_PIXELFORMAT_ARGB8888, surf32->pixels, surf32->pitch) == 0) {
        SDL_Surface *rgb_surf = SDL_ConvertSurfaceFormat(surf32, SDL_PIXELFORMAT_RGB24, 0);
        if (rgb_surf) {
          if (SDL_SaveBMP(rgb_surf, phases[phase].filename) == 0) {
            printf("[CPU-OPT] ✓ Exported %s (%.2f ms, %" PRIu64 " voxels, %" PRIu64 " chunks)\n",
                   phases[phase].filename, render_time_ms, stats.voxels_rendered, stats.chunks_processed);
          } else {
            printf("[CPU-OPT] ✗ Failed to save %s\n", phases[phase].filename);
          }
          SDL_FreeSurface(rgb_surf);
        }
      }
      SDL_FreeSurface(surf32);
    }

    // Print performance summary
    printf("[CPU-OPT] Performance: %.2f ms, %.1f FPS, Culling: %.1f%%\n",
           render_time_ms, 1000.0 / render_time_ms,
           stats.voxels_processed > 0 ? (100.0 * stats.voxels_culled) / stats.voxels_processed : 0.0);
  }

  printf("[CPU-OPT] All optimization phases completed!\n");
}

// Render with sprite renderer at different optimization levels and export bitmaps
static void render_sprite_optimization_phases(SDL_Renderer *ren, IsometricRenderer *ir, int screen_w, int screen_h)
{
  printf("[SPRITE-OPT] Rendering optimization phases...\n");

  // Create sprite renderer
  SpriteRenderer* sprite_renderer = sprite_renderer_create(ren, NULL);
  if (!sprite_renderer) {
    printf("[SPRITE-OPT] Failed to create sprite renderer!\n");
    return;
  }

  // Define optimization phases to test
  struct {
    const char *name;
    const char *filename;
    SpriteRenderOptimizations flags;
  } phases[] = {
    {"No Optimizations", "assets/sprite_phase_none.bmp", SPRITE_RENDER_OPT_NONE},
    {"Screen Culling", "assets/sprite_phase_screen.bmp", SPRITE_RENDER_OPT_SCREEN_CULLING},
    {"Sprite Caching", "assets/sprite_phase_cache.bmp", SPRITE_RENDER_OPT_SCREEN_CULLING | SPRITE_RENDER_OPT_SPRITE_CACHING},
    {"Batch Rendering", "assets/sprite_phase_batch.bmp", SPRITE_RENDER_OPT_SCREEN_CULLING | SPRITE_RENDER_OPT_SPRITE_CACHING | SPRITE_RENDER_OPT_BATCH_RENDERING},
    {"Depth Sorting", "assets/sprite_phase_depth.bmp", SPRITE_RENDER_OPT_SCREEN_CULLING | SPRITE_RENDER_OPT_SPRITE_CACHING | SPRITE_RENDER_OPT_BATCH_RENDERING | SPRITE_RENDER_OPT_DEPTH_SORTING},
    {"All Optimizations", "assets/sprite_phase_all.bmp", SPRITE_RENDER_OPT_ALL}
  };

  int num_phases = sizeof(phases) / sizeof(phases[0]);

  for (int phase = 0; phase < num_phases; phase++) {
    printf("[SPRITE-OPT] Phase %d/%d: %s\n", phase + 1, num_phases, phases[phase].name);

    // Set optimization flags
    sprite_renderer_set_optimizations(&sprite_renderer->config, phases[phase].flags);

    // Reset statistics
    sprite_renderer_reset_stats(sprite_renderer);

    // Render frame
    uint64_t start_time = get_time_ns();
    sprite_renderer_render(sprite_renderer, ir, ren, ir->game_worlds->home_world);
    uint64_t render_time_ns = get_time_ns() - start_time;
    double render_time_ms = render_time_ns / 1000000.0;

    // Get statistics
    SpriteRendererStats stats = sprite_renderer_get_stats(sprite_renderer);

    // Export bitmap using the same approach as CPU renderer
    SDL_Surface *surf32 = SDL_CreateRGBSurfaceWithFormat(0, screen_w, screen_h, 32, SDL_PIXELFORMAT_ARGB8888);
    if (surf32) {
      if (SDL_RenderReadPixels(ren, NULL, SDL_PIXELFORMAT_ARGB8888, surf32->pixels, surf32->pitch) == 0) {
        SDL_Surface *rgb_surf = SDL_ConvertSurfaceFormat(surf32, SDL_PIXELFORMAT_RGB24, 0);
        if (rgb_surf) {
          if (SDL_SaveBMP(rgb_surf, phases[phase].filename) == 0) {
            printf("[SPRITE-OPT] ✓ Exported %s (%.2f ms, %" PRIu64 " voxels, %" PRIu64 " sprites)\n",
                   phases[phase].filename, render_time_ms, stats.voxels_rendered, stats.sprites_generated);
          } else {
            printf("[SPRITE-OPT] ✗ Failed to save %s\n", phases[phase].filename);
          }
          SDL_FreeSurface(rgb_surf);
        }
      }
      SDL_FreeSurface(surf32);
    }

    // Print performance
    printf("[SPRITE-OPT] Performance: %.2f ms, %.1f FPS, Culling: %.1f%%\n",
           render_time_ms, 1000.0 / render_time_ms,
           stats.voxels_processed > 0 ? (100.0 * stats.voxels_culled) / stats.voxels_processed : 0.0);
  }

  // Clean up
  sprite_renderer_destroy(sprite_renderer);
  printf("[SPRITE-OPT] All optimization phases completed!\n");
}

// Generate reference outputs for all world types including top-down views
static void generate_world_type_references(SDL_Renderer *ren, IsometricRenderer *ir, int screen_w, int screen_h)
{
  printf("[WORLD-REF] Generating reference outputs for all world types...\n");

  // Define world types to test
  struct {
    const char *name;
    const char *filename;
    WorldGenerationType type;
    const char *seed;
  } world_types[] = {
    {"HOME", "assets/world_type_home.bmp", WORLD_TYPE_HOME, "home_reference_seed"},
    {"FARM", "assets/world_type_farm.bmp", WORLD_TYPE_FARM, "farm_reference_seed"},
    {"RANDOM", "assets/world_type_random.bmp", WORLD_TYPE_RANDOM, "random_reference_seed"},
    {"WILDERNESS", "assets/world_type_wilderness.bmp", WORLD_TYPE_WILDERNESS, "wilderness_reference_seed"},
    {"SOLID", "assets/world_type_solid.bmp", WORLD_TYPE_SOLID, "solid_reference_seed"},
    {"UNDERWORLD", "assets/world_type_underworld.bmp", WORLD_TYPE_UNDERWORLD, "underworld_reference_seed"},
    {"SCOURED", "assets/world_type_scoured.bmp", WORLD_TYPE_SCOURED, "scoured_reference_seed"},
    {"LABYRINTH", "assets/world_type_labyrinth.bmp", WORLD_TYPE_LABYRINTH_SQUARE, "labyrinth_reference_seed"},
    {"WFC_TOWN", "assets/world_type_wfc_town.bmp", WORLD_TYPE_WFC_TOWN, "wfc_town_reference_seed"},
    {"CLOUD", "assets/world_type_cloud.bmp", WORLD_TYPE_CLOUD, "cloud_reference_seed"},
    {"ARENA", "assets/world_type_arena.bmp", WORLD_TYPE_ARENA, "arena_reference_seed"}
  };

  int num_types = sizeof(world_types) / sizeof(world_types[0]);

    for (int type_idx = 0; type_idx < num_types; type_idx++) {
    printf("[WORLD-REF] Processing %s world type...\n", world_types[type_idx].name);

    // Create a test world for this specific type
    World *test_world = world_create(WORLD_SIZE_X, WORLD_SIZE_Y, WORLD_SIZE_Z);
    if (!test_world) {
      printf("[WORLD-REF] Failed to create test world for %s\n", world_types[type_idx].name);
      continue;
    }

    // Generate the world with the specific type
    world_generate_with_type(test_world, world_types[type_idx].seed, world_types[type_idx].type);

    // Temporarily set the world in the renderer so CPU renderer can access it
    World* original_world = ir->game_worlds->home_world;
    ir->game_worlds->home_world = test_world;

        // Debug: Check what's in the generated world
    printf("[WORLD-REF] Generated %s world: %dx%dx%d\n", world_types[type_idx].name,
           (int)test_world->width, (int)test_world->height, (int)test_world->depth);

    // Check a few voxels to see if they're not all AIR
    int check_x = test_world->width / 2;
    int check_y = test_world->height / 2;
    int check_z = test_world->depth / 2;
    Voxel *check_voxel = world_pos_in_bounds_fast(test_world, check_x, check_y, check_z) ?
                         world_voxel_ptr_fast(test_world, check_x, check_y, check_z) : NULL;
    if (check_voxel) {
      printf("[WORLD-REF] Center voxel (%d,%d,%d): type=%d\n", check_x, check_y, check_z, check_voxel->type);
    } else {
      printf("[WORLD-REF] Center voxel (%d,%d,%d): OUT_OF_BOUNDS\n", check_x, check_y, check_z);
    }

    // Check a few more positions to see if there are any non-AIR voxels
    int check_positions[][3] = {{32, 32, 32}, {96, 96, 96}, {64, 64, 32}, {64, 64, 96}};
    for (int i = 0; i < 4; i++) {
      int x = check_positions[i][0], y = check_positions[i][1], z = check_positions[i][2];
      Voxel *v = world_pos_in_bounds_fast(test_world, x, y, z) ?
                  world_voxel_ptr_fast(test_world, x, y, z) : NULL;
      if (v && v->type != VOXEL_AIR) {
        printf("[WORLD-REF] Found non-AIR voxel at (%d,%d,%d): type=%d\n", x, y, z, v->type);
        break;
      }
    }

    // Render isometric view using CPU renderer for consistency
    printf("[WORLD-REF] Rendering %s world with CPU renderer...\n", world_types[type_idx].name);

    // Clear renderer
    SDL_SetRenderDrawColor(ren, 20, 22, 35, 255);
    SDL_RenderClear(ren);

    // Render the world using CPU renderer with proper configuration (same as phases)
    CPURendererConfig config = {
      .flags = CPU_RENDER_OPT_ALL,
      .batch_size = 1024,
      .chunk_size_x = 16,
      .chunk_size_y = 16,
      .chunk_size_z = 256,
      .enable_grid = false,
      .enable_debug_overlay = false,
      .max_visible_voxels = 100000,
      .culling_margin = 32.0f
    };

    cpu_renderer_render_optimized(ir, ren, &config);

      // Export isometric view
      SDL_Surface *surf32 = SDL_CreateRGBSurfaceWithFormat(0, screen_w, screen_h, 32, SDL_PIXELFORMAT_ARGB8888);
      if (surf32) {
        if (SDL_RenderReadPixels(ren, NULL, SDL_PIXELFORMAT_ARGB8888, surf32->pixels, surf32->pitch) == 0) {
          SDL_Surface *rgb_surf = SDL_ConvertSurfaceFormat(surf32, SDL_PIXELFORMAT_RGB24, 0);
          if (rgb_surf) {
            if (SDL_SaveBMP(rgb_surf, world_types[type_idx].filename) == 0) {
              printf("[WORLD-REF] ✓ Exported %s\n", world_types[type_idx].filename);
            } else {
              printf("[WORLD-REF] ✗ Failed to save %s\n", world_types[type_idx].filename);
            }
            SDL_FreeSurface(rgb_surf);
          }
        }
        SDL_FreeSurface(surf32);
      }

      // Generate top-down view for selected world types
      if (strcmp(world_types[type_idx].name, "HOME") == 0 ||
          strcmp(world_types[type_idx].name, "FARM") == 0 ||
          strcmp(world_types[type_idx].name, "WILDERNESS") == 0 ||
          strcmp(world_types[type_idx].name, "ARENA") == 0) {

                char topdown_filename[256];
        char lower_name[32];
        strcpy(lower_name, world_types[type_idx].name);
        strtolower(lower_name);
        snprintf(topdown_filename, sizeof(topdown_filename), "assets/topdown_%s.bmp", lower_name);

        // Clear renderer for top-down view
        SDL_SetRenderDrawColor(ren, 20, 22, 35, 255);
        SDL_RenderClear(ren);

        // Render top-down view
        render_topdown_highest(ren, test_world, screen_w, screen_h);

        // Export top-down view
        SDL_Surface *topdown_surf = SDL_CreateRGBSurfaceWithFormat(0, screen_w, screen_h, 32, SDL_PIXELFORMAT_ARGB8888);
        if (topdown_surf) {
          if (SDL_RenderReadPixels(ren, NULL, SDL_PIXELFORMAT_ARGB8888, topdown_surf->pixels, topdown_surf->pitch) == 0) {
            SDL_Surface *topdown_rgb = SDL_ConvertSurfaceFormat(topdown_surf, SDL_PIXELFORMAT_RGB24, 0);
            if (topdown_rgb) {
              if (SDL_SaveBMP(topdown_rgb, topdown_filename) == 0) {
                printf("[WORLD-REF] ✓ Exported %s\n", topdown_filename);
              } else {
                printf("[WORLD-REF] ✗ Failed to save %s\n", topdown_filename);
              }
              SDL_FreeSurface(topdown_rgb);
            }
          }
          SDL_FreeSurface(topdown_surf);
        }
      }

      // Restore the original world and cleanup this test world
      ir->game_worlds->home_world = original_world;
      world_destroy(test_world);
  }



  printf("[WORLD-REF] All world type references generated!\n");
}

// Greedy-mesh top-down renderer: uses voxel_mesh_build_top_faces_greedy to draw
// maximal rectangles per z-slice, scaled to the provided screen size.
static void render_topdown_highest_greedy(SDL_Renderer *ren, const World *w, int screen_w, int screen_h)
{
  if (!ren || !w || screen_w <= 0 || screen_h <= 0)
    return;
  // Compute pixel scale (>=1) per voxel
  int cell_w = screen_w / (int)w->width;
  int cell_h = screen_h / (int)w->height;
  if (cell_w < 1)
    cell_w = 1;
  if (cell_h < 1)
    cell_h = 1;
  VoxelMesh m;
  voxel_mesh_init(&m);
  voxel_mesh_build_top_faces_greedy(w, &m);
  for (int i = 0; i < m.count; i++)
  {
    VoxelFaceQuad q = m.quads[i];
    // Color from representative voxel at (x0,y0,z0)
    Uint8 r = 20, g = 22, b = 35;
    const Voxel *v0 = world_voxel_cptr_fast((World *)w, q.x0, q.y0, q.z0);
    if (v0)
      world_voxel_type_color(v0->type, &r, &g, &b);
    SDL_SetRenderDrawColor(ren, r, g, b, 255);
    // Rectangle spans [x0..x1] and [y0..y1] inclusive in voxel coords
    SDL_Rect rect;
    rect.x = q.x0 * cell_w;
    rect.y = q.y0 * cell_h;
    rect.w = (q.x1 - q.x0 + 1) * cell_w;
    rect.h = (q.y1 - q.y0 + 1) * cell_h;
    SDL_RenderFillRect(ren, &rect);
  }
  voxel_mesh_free(&m);
}

// Validate top-down rendering by drawing at 1:1 pixel-per-voxel and comparing
// readback colors to expected colors from top-most voxel types.
static void validate_topdown_pixel_per_voxel(SDL_Renderer *ren, const World *w)
{
  if (!ren || !w)
    return;
  const int tw = (int)w->width;
  const int th = (int)w->height;
  SDL_Texture *tex = SDL_CreateTexture(ren, SDL_PIXELFORMAT_ARGB8888, SDL_TEXTUREACCESS_TARGET, tw, th);
  if (!tex)
  {
    fprintf(stderr, "Topdown 1x1: CreateTexture failed: %s\n", SDL_GetError());
    return;
  }
  // Render 1x1
  SDL_SetRenderTarget(ren, tex);
  render_topdown_highest(ren, w, tw, th);
  SDL_SetRenderTarget(ren, NULL);
  // Readback
  SDL_Surface *s = SDL_CreateRGBSurfaceWithFormat(0, tw, th, 32, SDL_PIXELFORMAT_ARGB8888);
  if (!s)
  {
    fprintf(stderr, "Topdown 1x1: CreateRGBSurface failed: %s\n", SDL_GetError());
    SDL_DestroyTexture(tex);
    return;
  }
  if (SDL_SetRenderTarget(ren, tex) == 0)
  {
    if (SDL_RenderReadPixels(ren, NULL, SDL_PIXELFORMAT_ARGB8888, s->pixels, s->pitch) != 0)
    {
      fprintf(stderr, "Topdown 1x1: SDL_RenderReadPixels failed: %s\n", SDL_GetError());
    }
    SDL_SetRenderTarget(ren, NULL);
  }
  // Compare each pixel to expected color derived from top voxel type
  int mismatches = 0;
  for (int y = 0; y < th; y++)
  {
    Uint8 *row = (Uint8 *)s->pixels + y * s->pitch;
    for (int x = 0; x < tw; x++)
    {
      // compute expected top voxel color
      int top_z = -1;
      for (int z = (int)w->depth - 1; z >= 0; z--)
      {
        const Voxel *vz = world_voxel_cptr_fast((World *)w, x, y, z);
        if (vz && vz->type != VOXEL_AIR)
        {
          top_z = z;
          break;
        }
      }
      Uint8 er = 20, eg = 22, eb = 35;
      if (top_z >= 0)
      {
        Voxel *v = world_get_voxel((World *)w, (uint32_t)x, (uint32_t)y, (uint32_t)top_z);
        if (v)
        {
          world_voxel_type_color(v->type, &er, &eg, &eb);
        }
      }
      Uint32 px = *(Uint32 *)(row + x * 4);
      Uint8 pr = (Uint8)((px >> 16) & 0xFF);
      Uint8 pg = (Uint8)((px >> 8) & 0xFF);
      Uint8 pb = (Uint8)(px & 0xFF);
      if (pr != er || pg != eg || pb != eb)
        mismatches++;
    }
  }
  if (mismatches == 0)
    printf("[universe-ref] topdown-1x1 validation: ok\n");
  else
    printf("[universe-ref] topdown-1x1 validation: fail (%d mismatched pixels)\n", mismatches);
  SDL_FreeSurface(s);
  SDL_DestroyTexture(tex);
}

